<?php
require_once __DIR__ . '/../core/Auth.php';require_once __DIR__ . '/../core/Database.php';require_once __DIR__ . '/../core/Response.php';require_once __DIR__ . '/../core/JalaliDate.php';require_once __DIR__ . '/../lib/OrgAccess.php';
Auth::requirePermission('hr_assessments.manage');$pageTitle='تخصیص آزمون‌های سازمانی';$user=Auth::user();$accessibleIds=OrgAccess::accessibleUserIds($user);if(!$accessibleIds)$accessibleIds=[-1];

function assessment_target_ids(string $scope,array $post,array $accessibleIds): array
{
    $base='SELECT u.id FROM users u WHERE u.status="active"';$params=[];
    if(in_array($scope,['employee','user'],true)){$base.=' AND u.id=?';$params[]=(int)($post['scope_value']??0);}
    elseif(in_array($scope,['multiple','users'],true))return array_values(array_intersect(array_values(array_unique(array_map('intval',$post['employee_ids']??[]))),$accessibleIds));
    elseif($scope==='unit'){$base.=' AND u.org_unit_id=?';$params[]=(int)($post['scope_value']??0);}
    elseif($scope==='role'){$base.=' AND u.org_role_id=?';$params[]=(int)($post['scope_value']??0);}
    elseif($scope==='sales_line'){$base.=' AND u.sales_line=?';$params[]=trim((string)($post['scope_value']??''));}
    elseif($scope==='supervisor_team'){$base.=' AND (u.parent_user_id=? OR u.supervisor_id=?)';$manager=(int)($post['scope_value']??0);$params=[$manager,$manager];}
    elseif($scope==='manager_team'){$manager=(int)($post['scope_value']??0);$context=OrgAccess::userContext($manager);return $context?array_values(array_intersect(array_values(array_diff(OrgAccess::accessibleUserIds($context),[$manager])),$accessibleIds)):[];}
    elseif($scope==='without_test'){$base.=' AND NOT EXISTS(SELECT 1 FROM hr_assessment_assignments a WHERE a.employee_id=u.id AND a.test_id=? AND COALESCE(a.period_key,"")=? AND a.status IN("assigned","in_progress","submitted"))';$params[]=(int)($post['test_id']??0);$params[]=trim((string)($post['period_key']??''));}
    elseif(!in_array($scope,['company','active_users'],true))return [];
    $ids=array_map('intval',array_column(Database::fetchAll($base,$params),'id'));
    return array_values(array_intersect($ids,$accessibleIds));
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/employee-assessments.php');}
    $action=(string)($_POST['action']??'assign');
    try{
        if($action==='assign'){
            $rawScope=in_array($_POST['assignment_scope']??'', ['employee','multiple','user','users','company','unit','role','sales_line','supervisor_team','manager_team','without_test','active_users'],true)?$_POST['assignment_scope']:'user';$scope=$rawScope==='employee'?'user':($rawScope==='multiple'?'users':$rawScope);
            $testId=(int)($_POST['test_id']??0);$period=trim((string)($_POST['period_key']??''));$dueInput=trim((string)($_POST['due_date']??''));$due=JalaliDate::toGregorian($dueInput)?:null;$targets=assessment_target_ids($scope,$_POST,$accessibleIds);
            if(!Database::fetch('SELECT id FROM hr_assessment_tests WHERE id=? AND active=1',[$testId]))throw new InvalidArgumentException('آزمون فعال و معتبر انتخاب نشده است.');
            if($dueInput!==''&&!$due)throw new InvalidArgumentException('تاریخ مهلت معتبر نیست.');
            if(!$targets)throw new InvalidArgumentException('هیچ کاربر فعالی برای این دامنه پیدا نشد.');
            if(!OrgAccess::canAssignScope($user,$targets))throw new InvalidArgumentException('برای تخصیص به بخشی از کاربران انتخاب‌شده دسترسی ندارید.');
            $allowRetake=isset($_POST['allow_retake'])?1:0;$batchKey=in_array($scope,['users','company','unit','role','sales_line','supervisor_team','manager_team','without_test','active_users'],true)?date('YmdHis').'-'.bin2hex(random_bytes(5)):null;$scopeValue=$scope==='users'?implode(',',array_map('intval',$targets)):trim((string)($_POST['scope_value']??''));
            $created=0;$duplicates=0;$failed=0;
            foreach($targets as $employeeId){
                try{$employee=OrgAccess::userContext($employeeId);if(!$employee){$failed++;continue;}if(!$allowRetake){$exists=Database::fetch('SELECT id FROM hr_assessment_assignments WHERE test_id=? AND employee_id=? AND COALESCE(period_key,"")=? AND status IN("assigned","in_progress","submitted") LIMIT 1',[$testId,$employeeId,$period]);if($exists){$duplicates++;continue;}}Database::execute('INSERT INTO hr_assessment_assignments(test_id,employee_id,department,role_key,sales_line,supervisor_id,manager_id,assigned_by,assignment_scope,batch_key,scope_type,scope_value,period_key,due_date,allow_retake,show_result_to_employee,initial_status,status,notes,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,"assigned",?,NOW(),NOW())',[$testId,$employeeId,$employee['org_unit_title']?:$employee['department'],$employee['org_role_code']?:$employee['role_key'],$employee['sales_line'],$employee['supervisor_id'],$employee['organization_manager_id'],(int)$user['id'],$scope,$batchKey,$scope,$scopeValue,$period,$due,$allowRetake,isset($_POST['show_result_to_employee'])?1:0,'assigned',trim((string)($_POST['notes']??''))]);$created++;}catch(Throwable $e){$failed++;error_log('Assessment target '.$employeeId.': '.$e->getMessage());}}
            flash("نتیجه تخصیص: {$created} ایجاد شد، {$duplicates} تکراری بود و {$failed} خطا داشت.",$failed?'danger':'success');
        }elseif($action==='extend'){
            $assignmentId=(int)($_POST['assignment_id']??0);$dueInput=trim((string)($_POST['due_date']??''));$due=JalaliDate::toGregorian($dueInput);$assignment=Database::fetch('SELECT id,employee_id,status,due_date FROM hr_assessment_assignments WHERE id=?',[$assignmentId]);
            if(!$assignment||!OrgAccess::canAccessUser($user,(int)$assignment['employee_id']))throw new InvalidArgumentException('تخصیص موردنظر در دسترس نیست.');
            if(!$due)throw new InvalidArgumentException('مهلت جدید معتبر نیست.');
            if(in_array($assignment['status'],['submitted','cancelled'],true))throw new InvalidArgumentException('مهلت تخصیص نهایی یا لغوشده قابل تغییر نیست.');
            Database::execute('UPDATE hr_assessment_assignments SET due_date=?,status=IF(status="expired","assigned",status),updated_at=NOW() WHERE id=?',[$due,$assignmentId]);Database::execute('INSERT INTO hr_assessment_assignment_logs(assignment_id,action,reason,performed_by,old_status,new_status,created_at) VALUES (?,"extend_due_date",?,?,?,IF(?="expired","assigned",?),NOW())',[$assignmentId,'مهلت قبلی: '.($assignment['due_date']?:'-'),(int)$user['id'],$assignment['status'],$assignment['status'],$assignment['status']]);flash('مهلت انجام آزمون تمدید شد.');
        }elseif($action==='cancel'){
            $assignmentId=(int)($_POST['assignment_id']??0);$reason=trim((string)($_POST['cancel_reason']??''));$assignment=Database::fetch('SELECT a.*,r.id response_id FROM hr_assessment_assignments a LEFT JOIN hr_assessment_responses r ON r.assignment_id=a.id WHERE a.id=?',[$assignmentId]);
            if(!$assignment||!OrgAccess::canAccessUser($user,(int)$assignment['employee_id']))throw new RuntimeException('not_found');
            if($assignment['status']==='submitted'&&!Auth::isSuperAdmin())throw new InvalidArgumentException('لغو آزمون ثبت نهایی‌شده فقط برای سوپرادمین مجاز است.');
            if($assignment['status']==='in_progress'&&$reason==='')throw new InvalidArgumentException('ثبت دلیل برای لغو آزمون شروع‌شده الزامی است.');
            $old=$assignment['status'];Database::execute('UPDATE hr_assessment_assignments SET status="cancelled",cancel_reason=?,cancelled_by=?,cancelled_at=NOW(),archived_at='.($old==='submitted'?'NOW()':'archived_at').',updated_at=NOW() WHERE id=?',[$reason,(int)$user['id'],$assignmentId]);Database::execute('INSERT INTO hr_assessment_assignment_logs(assignment_id,action,reason,performed_by,old_status,new_status,created_at) VALUES (?,?,?,?,?,"cancelled",NOW())',[$assignmentId,$old==='assigned'?'cancel_before_start':($old==='submitted'?'archive_submitted':'cancel_in_progress'),$reason,(int)$user['id'],$old]);flash($old==='assigned'?'تخصیص شروع‌نشده به‌صورت امن لغو شد.':'تخصیص با ثبت دلیل لغو شد.');
        }
    }catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Assessment management: '.$e->getMessage());flash('عملیات انجام نشد. لطفاً دوباره تلاش کنید.','danger');}
    redirect('/admin/employee-assessments.php');
}

$ph=implode(',',array_fill(0,count($accessibleIds),'?'));$tests=Database::fetchAll('SELECT id,title FROM hr_assessment_tests WHERE active=1 ORDER BY sort_order,title');$employees=Database::fetchAll("SELECT u.id,u.name,COALESCE(ou.title,u.department) unit_title,COALESCE(r.title,u.role_key) role_title FROM users u LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles r ON r.id=u.org_role_id WHERE u.status='active' AND u.id IN ({$ph}) ORDER BY u.name",$accessibleIds);$units=Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title');$roles=Database::fetchAll('SELECT id,title FROM org_roles WHERE active=1 ORDER BY sort_order,title');$managers=Database::fetchAll("SELECT id,name FROM users WHERE status='active' AND id IN ({$ph}) AND (access_scope IN ('team','unit','all') OR role IN ('manager','admin','super_admin')) ORDER BY name",$accessibleIds);
$where=["a.employee_id IN ({$ph})"];$params=$accessibleIds;foreach(['test_id'=>'a.test_id','employee_id'=>'a.employee_id','status'=>'a.status','assigned_by'=>'a.assigned_by'] as $key=>$column){$value=trim((string)($_GET[$key]??''));if($value!==''){$where[]="{$column}=?";$params[]=$key==='status'?$value:(int)$value;}}if(trim((string)($_GET['period_key']??''))!==''){$where[]='a.period_key=?';$params[]=trim($_GET['period_key']);}
foreach(['org_unit_id'=>'u.org_unit_id','org_role_id'=>'u.org_role_id'] as $key=>$column){$value=(int)($_GET[$key]??0);if($value){$where[]="{$column}=?";$params[]=$value;}}
foreach(['supervisor_id'=>'a.supervisor_id','manager_id'=>'a.manager_id'] as $key=>$column){$value=(int)($_GET[$key]??0);if($value){$where[]="{$column}=?";$params[]=$value;}}
if(trim((string)($_GET['sales_line']??''))!==''){$where[]='a.sales_line=?';$params[]=trim((string)$_GET['sales_line']);}
if(($from=JalaliDate::toGregorian($_GET['date_from']??''))){$where[]='DATE(a.created_at)>=?';$params[]=$from;}
if(($to=JalaliDate::toGregorian($_GET['date_to']??''))){$where[]='DATE(a.created_at)<=?';$params[]=$to;}
$assignments=Database::fetchAll('SELECT a.*,u.name employee_name,COALESCE(ou.title,u.department) unit_title,COALESCE(orr.title,u.role_key) role_title,t.title test_title,assigner.name assigned_by_name,sup.name supervisor_name,mgr.name manager_name FROM hr_assessment_assignments a JOIN users u ON u.id=a.employee_id JOIN hr_assessment_tests t ON t.id=a.test_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles orr ON orr.id=u.org_role_id LEFT JOIN users assigner ON assigner.id=a.assigned_by LEFT JOIN users sup ON sup.id=a.supervisor_id LEFT JOIN users mgr ON mgr.id=a.manager_id WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC LIMIT 200',$params);
require __DIR__ . '/../views/partials/admin-header.php';
?>
<div class="section-heading-row"><div><h1>تخصیص آزمون سازمانی</h1><p class="muted">تخصیص گروهی به رکوردهای مستقل و قابل کنترل تبدیل می‌شود.</p></div><a class="btn" href="/admin/hr-assessment-results.php">نتایج آزمون‌ها</a></div>
<section class="card admin-form"><h2>تخصیص جدید</h2><form method="post" id="assignmentForm"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="assign"><div class="grid grid-3"><label class="form-field"><span>آزمون</span><select name="test_id" required><?php foreach($tests as $item):?><option value="<?=$item['id']?>"><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>دامنه تخصیص</span><select name="assignment_scope" id="assignmentScope"><option value="employee">یک کاربر خاص</option><option value="multiple">چند کاربر انتخابی</option><option value="company">کل کاربران</option><option value="unit">واحد سازمانی</option><option value="role">نقش سازمانی</option><option value="sales_line">لاین فروش</option><option value="supervisor_team">تیم سرپرست</option><option value="manager_team">تیم مدیر فروش</option><option value="without_test">کاربران بدون آزمون در دوره</option><option value="active_users">کاربران فعال فقط</option></select></label><label class="form-field" data-scope-control="employee"><span>کاربر</span><select name="scope_value"><?php foreach($employees as $item):?><option value="<?=$item['id']?>"><?=e($item['name'].' - '.$item['unit_title'])?></option><?php endforeach?></select></label><label class="form-field" data-scope-control="multiple" hidden><span>جستجو و انتخاب کاربران</span><input type="search" id="employeeSearch" placeholder="جستجوی نام"><select name="employee_ids[]" id="employeeMulti" multiple size="7"><?php foreach($employees as $item):?><option value="<?=$item['id']?>"><?=e($item['name'].' - '.$item['unit_title'].' - '.$item['role_title'])?></option><?php endforeach?></select></label><label class="form-field" data-scope-control="unit" hidden><span>واحد</span><select data-scope-value><?php foreach($units as $item):?><option value="<?=$item['id']?>"><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field" data-scope-control="role" hidden><span>نقش</span><select data-scope-value><?php foreach($roles as $item):?><option value="<?=$item['id']?>"><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field" data-scope-control="sales_line" hidden><span>لاین فروش</span><input data-scope-value></label><label class="form-field" data-scope-control="supervisor_team manager_team" hidden><span>مدیر یا سرپرست</span><select data-scope-value><?php foreach($managers as $item):?><option value="<?=$item['id']?>"><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>دوره</span><input name="period_key"></label><label class="form-field"><span>مهلت انجام</span><input class="jalali-date-input" name="due_date"></label><label class="form-field"><span>وضعیت اولیه</span><select disabled><option>تخصیص داده‌شده</option></select></label><label class="checkbox-item"><input type="checkbox" name="allow_retake"> اجازه تکرار</label><label class="checkbox-item"><input type="checkbox" name="show_result_to_employee"> نمایش نتیجه به کارمند</label><label class="form-field grid-span-2"><span>توضیحات</span><input name="notes"></label></div><button class="btn btn-primary">ثبت تخصیص</button></form></section>
<form class="card admin-form" method="get"><h2>فیلتر تخصیص‌ها</h2><div class="grid grid-3"><label class="form-field"><span>آزمون</span><select name="test_id"><option value="">همه</option><?php foreach($tests as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['test_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>کاربر</span><select name="employee_id"><option value="">همه</option><?php foreach($employees as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['employee_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><?php foreach(['assigned'=>'تخصیص داده‌شده','in_progress'=>'در حال انجام','submitted'=>'ثبت نهایی','cancelled'=>'لغوشده','expired'=>'منقضی'] as $value=>$label):?><option value="<?=$value?>" <?=($_GET['status']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label class="form-field"><span>دوره</span><input name="period_key" value="<?=e($_GET['period_key']??'')?>"></label></div><button class="btn btn-primary">اعمال فیلتر</button></form>
