<script>const scope=document.getElementById('assignmentScope'),form=document.getElementById('assignmentForm');function syncScope(){document.querySelectorAll('[data-scope-control]').forEach(el=>el.hidden=!el.dataset.scopeControl.split(' ').includes(scope.value));}scope.addEventListener('change',syncScope);syncScope();form.addEventListener('submit',event=>{if(scope.value==='company'&&!confirm('این آزمون برای همه کاربران فعال تخصیص داده می‌شود. ادامه می‌دهید؟')){event.preventDefault();return;}const control=[...document.querySelectorAll('[data-scope-control]')].find(el=>el.dataset.scopeControl.split(' ').includes(scope.value));const value=control?.querySelector('[data-scope-value]');if(value){let hidden=form.querySelector('input[name="scope_value"]');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='scope_value';form.append(hidden);}hidden.value=value.value;}});document.getElementById('employeeSearch')?.addEventListener('input',event=>{const term=event.target.value.trim().toLowerCase();[...document.getElementById('employeeMulti').options].forEach(option=>option.hidden=term!==''&&!option.textContent.toLowerCase().includes(term));});</script>
